// clock.component.ts
import { Component } from '@angular/core';
import { interval } from 'rxjs';
import { map } from 'rxjs/operators';

@Component({
  selector: 'app-clock',
  template: `<h1>{{ clock$ | async }}</h1>`
})
export class ClockComponent {
  clock$ = interval(1000).pipe(
    map(() => new Date().toLocaleTimeString())
  );
}
